test('cancellation releases a range reader and leaves the shared index reusable',async t=>{
  const f=await fixture(t),e=f.epoch,file=f.file('eventJournalDir');
  await fs.writeFile(file,Array.from({length:12000},(_,i)=>JSON.stringify(event(e+i/100,'e'+i))).join('\n')+'\n');
  const controller=new AbortController();
  let consumed=0;
  await assert.rejects(readNdjsonRange(file,e,e+120,()=>{consumed++;controller.abort();},true,{signal:controller.signal}),{name:'AbortError'});
  assert.equal(consumed,1);
  const rows=[];await readNdjsonRange(file,e,e,row=>rows.push(row),true);
  assert.deepEqual(rows.map(r=>r.record_id),['e0']);
  const cold=f.file('eventJournalDir','.part1');await fs.copyFile(file,cold);
  const detached=new AbortController();
  const pending=readNdjsonRange(cold,e,e,()=>assert.fail('detached reader must not consume'),true,{signal:detached.signal});
  detached.abort();await assert.rejects(pending,{name:'AbortError'});
  const remaining=[];await readNdjsonRange(cold,e,e,row=>remaining.push(row),true);
  assert.equal(remaining.length,1);
});

